  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Intraperitoneal NMN in mice increased brain NAD+ within 15 minutes, directly demonstrating systemic administration can achieve BBB crossing and CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "In a rat tissue distribution study, hydroxysafflor yellow A reached 1026 ng/g in brain, indicating meaningful BBB permeation under normal conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "PET evidence for [18F]FLT describes limited BBB permeability, arguing against meaningful CNS access for that molecule, though this is less condition-matched than the positive systemic in-vivo evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The majority of retrieved molecules show direct in-vivo evidence of brain or CSF exposure after systemic administration, including brain concentration measurements, CSF detection, brain NAD+ increases, and high brain uptake. One PET record indicates limited BBB permeability, but it is outweighed by the consistent positive systemic evidence.",
  "evidence_gaps": [
    "Molecule 8 has conflicting BBB permeability reports (disrupted-barrier glioma uptake vs limited permeability), reducing the weight of the negative evidence.",
    "Several positive records rely on indirect pharmacodynamic or tracer detection rather than direct unbound brain concentration measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

